t.script:
(function () {
    var canvas = document.getElementById('firma_canvas');
    var wrapper = document.getElementById('canvas_contenedor');
    var esMobile = window.innerWidth < 768;

    // En mobile el canvas es internamente un lienzo
    // "horizontal" normal (igual que en escritorio), pero
    // se rota -90° con CSS para que visualmente llene un
    // recuadro portrait (alto y angosto) — así la firma
    // aprovecha el lado largo del teléfono como su ancho
    // natural. La rotación es solo visual: lo que se
    // exporta sigue siendo el lienzo horizontal: no se
    // debe aplicar una segunda rotación al bitmap.
    // posicion(), más abajo, deshace esa rotación para
    // saber dónde cae realmente el dedo del usuario dentro
    // del lienzo.
    var dpr = window.devicePixelRatio || 1;
    var anchoDisponible = wrapper.clientWidth;
    var cssWCanvas, cssHCanvas;

    if (esMobile) {
        var altoWrapper = Math.round(anchoDisponible * 1.3);
        wrapper.style.height = altoWrapper + 'px';
        wrapper.style.overflow = 'hidden';
        // Lienzo interno "horizontal": su ancho propio es el
        // alto visible del recuadro (el lado largo), y su
        // alto propio es el ancho visible del recuadro.
        cssWCanvas = altoWrapper;
        cssHCanvas = anchoDisponible;
    } else {
        cssWCanvas = anchoDisponible;
        cssHCanvas = 200;
    }

    canvas.width = Math.round(cssWCanvas * dpr);
    canvas.height = Math.round(cssHCanvas * dpr);
    canvas.style.width = cssWCanvas + 'px';
    canvas.style.height = cssHCanvas + 'px';

    if (esMobile) {
        canvas.style.position = 'absolute';
        canvas.style.top = '50%';
        canvas.style.left = '50%';
        canvas.style.transform = 'translate(-50%, -50%) rotate(-90deg)';
    }

    var ctx = canvas.getContext('2d');
    ctx.lineWidth = 2 * dpr;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#000';

    var dibujando = false;
    var hayTrazo = false;
    var btnFirmar = document.getElementById('btn_firmar');
    var checkConsentimiento = document.getElementById('consentimiento_check');
    var placeholderFirma = document.getElementById('placeholder_firma');

    function actualizarBoton() {
        btnFirmar.disabled = !(hayTrazo && checkConsentimiento.checked);
    }

    checkConsentimiento.addEventListener('change', actualizarBoton);

    var wrapperDocumento = document.getElementById('documento_wrapper');
    var btnToggleDocumento = document.getElementById('btn_toggle_documento');
    var labelToggleDocumento = document.getElementById('toggle_documento_label');

    // El colapso por defecto en pantallas chicas lo decide el
    // CSS de arriba (@media), no JS — así reacciona en vivo a
    // cambios de tamaño/rotación, no solo al cargar la página.
    // El botón solo agrega/quita una clase que fuerza mostrarlo.
    function actualizarLabelToggle() {
        var visible = window.getComputedStyle(wrapperDocumento).display !== 'none';
        labelToggleDocumento.textContent = visible ? 'Ocultar documento' : 'Ver documento';
    }

    btnToggleDocumento.addEventListener('click', function () {
        wrapperDocumento.classList.toggle('mostrar_documento');
        actualizarLabelToggle();
    });

    actualizarLabelToggle();

    function posicion(evt) {
        var rect = canvas.getBoundingClientRect();

        if (!esMobile) {
            var escalaX = canvas.width / rect.width;
            var escalaY = canvas.height / rect.height;
            return {
                x: (evt.clientX - rect.left) * escalaX,
                y: (evt.clientY - rect.top) * escalaY
            };
        }

        // Mobile: el canvas está rotado -90° con CSS. rect
        // (getBoundingClientRect) ya viene en espacio de
        // pantalla (rotado); para saber dónde cae el toque
        // DENTRO del lienzo hay que deshacer esa rotación
        // respecto al centro del elemento.
        var centerX = rect.left + rect.width / 2;
        var centerY = rect.top + rect.height / 2;
        var dx = evt.clientX - centerX;
        var dy = evt.clientY - centerY;
        // Inversa de rotate(-90deg): (dx,dy) en pantalla
        // corresponde a (localDx,localDy) = (-dy, dx) en el
        // sistema propio (sin rotar) del canvas.
        var localDx = -dy;
        var localDy = dx;

        var cssW = canvas.offsetWidth;
        var cssH = canvas.offsetHeight;
        return {
            x: (localDx + cssW / 2) * (canvas.width / cssW),
            y: (localDy + cssH / 2) * (canvas.height / cssH)
        };
    }

    canvas.addEventListener('pointerdown', function (evt) {
        dibujando = true;
        placeholderFirma.style.display = 'none';
        var p = posicion(evt);
        ctx.beginPath();
        ctx.moveTo(p.x, p.y);
        canvas.setPointerCapture(evt.pointerId);
    });

    canvas.addEventListener('pointermove', function (evt) {
        if (!dibujando) { return; }
        var p = posicion(evt);
        ctx.lineTo(p.x, p.y);
        ctx.stroke();
        hayTrazo = true;
        actualizarBoton();
    });

    function terminarTrazo() { dibujando = false; }
    canvas.addEventListener('pointerup', terminarTrazo);
    canvas.addEventListener('pointercancel', terminarTrazo);
    canvas.addEventListener('pointerleave', terminarTrazo);

    document.getElementById('btn_limpiar').addEventListener('click', function () {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        hayTrazo = false;
        placeholderFirma.style.display = '';
        actualizarBoton();
    });

    function exportarFirma() {
        // posicion() ya deshace el giro CSS. Exportar el lienzo
        // completo: cada coordenada relativa ocupa el mismo lugar
        // en la caja horizontal 3:1, también desde el canvas móvil.
        if (!hayTrazo) { return null; }
        var salida = document.createElement('canvas');
        salida.width = 600;
        salida.height = 200;
        salida.getContext('2d').drawImage(canvas, 0, 0, 600, 200);
        return salida.toDataURL('image/png');
    }

    var procesando = false;
    document.getElementById('firma_form').addEventListener('submit', function (evt) {
        if (procesando) { evt.preventDefault(); return; }
        var firma = exportarFirma();
        if (!firma || !checkConsentimiento.checked) { evt.preventDefault(); return; }
        procesando = true;
        document.getElementById('firma_base64_input').value = firma;

        btnFirmar.innerHTML = '<span class="spinner-border spinner-border-sm" role="status"></span> Firmando documento...';
        document.getElementById('mensaje_procesando').style.display = 'block';

        // Deshabilitar en el siguiente tick: si se deshabilita
        // el checkbox dentro de este mismo handler de submit,
        // el navegador lo excluye del formulario ANTES de
        // enviarlo (un campo disabled no viaja en el POST),
        // así que el "consentimiento" marcado se perdía y el
        // servidor lo rechazaba aunque el usuario sí lo
        // hubiera aceptado.
        setTimeout(function () {
            btnFirmar.disabled = true;
            document.getElementById('btn_limpiar').disabled = true;
            checkConsentimiento.disabled = true;
        }, 0);
    });
})();
